#include <iostream>
#include <vector>
using namespace std;

int main() {
    // Precompute Fibonacci numbers up to > 10^18
    // Using F[1]=1, F[2]=2, F[3]=3, F[4]=5, ...
    vector<long long> fib;
    fib.push_back(1); // fib[0] = F[1] = 1
    fib.push_back(2); // fib[1] = F[2] = 2
    while (true) {
        long long next = fib[fib.size()-1] + fib[fib.size()-2];
        if (next > 2000000000000000000LL) break;
        fib.push_back(next);
    }

    int t;
    cin >> t;
    while (t--) {
        long long n;
        cin >> n;

        // Find Zeckendorf representation (greedy algorithm)
        // Positions are 0-indexed in the fib array
        vector<int> positions;
        long long remaining = n;

        for (int i = (int)fib.size() - 1; i >= 0; i--) {
            if (fib[i] <= remaining) {
                positions.push_back(i);
                remaining -= fib[i];
            }
        }

        // Add virtual position -1 (represents "before" the first Fibonacci number)
        positions.push_back(-1);

        // Compute the answer as product of contributions from each gap
        long long ans = 1;
        for (size_t i = 0; i < positions.size() - 1; i++) {
            long long gap = positions[i] - positions[i+1] - 1;
            long long contribution = (gap + 2) / 2;
            ans *= contribution;
        }

        cout << ans << endl;
    }

    return 0;
}
